def greet(name: str) -> str:
    """Greet a person by name."""
    return f"Hello, {name}"


def calculate_sum(a: int, b: int) -> int:
    """Add two numbers."""
    return a + b


class Calculator:
    """A simple calculator class."""

    def add(self, a: int, b: int) -> int:
        return a + b

    def multiply(self, a: int, b: int) -> int:
        return a * b


